import{_ as e,o as a,c as i,a5 as r,a6 as s}from"./chunks/framework.CQwNn0Y-.js";const x=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ZenFile","text":"原生 Win32 文件管理器","tagline":"轻量 · 原生 · 高性能 · 可拓展","image":{"src":"/images/home.png","alt":"ZenFile 主界面"},"actions":[{"theme":"brand","text":"开始使用","link":"/guide/install"},{"theme":"alt","text":"开发文档","link":"/docs/new-plugin"}]},"features":[{"title":"真正的原生","details":"Win32 消息循环 + GDI 自绘，不依赖 Electron、Qt、WebView2、Node.js 或 .NET 运行时。单文件可执行文件 1.48 MiB。"},{"title":"1.48 MiB","details":"主程序体积。空闲常驻内存 29.5 MB，约为 Windows 资源管理器的一半。"},{"title":"自绘传输引擎","details":"不用 IFileOperation。按文件大小分三条路径，4.7 GiB 大文件 5.78 s，已追平资源管理器。"},{"title":"进程级插件","details":"插件是 ZenFile.exe --plugin <id> 拉起的独立进程。崩溃不带崩宿主，Job Object 兜底。"},{"title":"完全可配置","details":"8 个设置页：界面布局、外观、交互、右键菜单、快捷键、高级、插件、关于。"},{"title":"全量实测数据","details":"与资源管理器 / Pulse 的对比全部为本机实测，每项写明口径与判据，无厂商宣传数字。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1792245757000}'),d={name:"index.md"};function l(n,t,o,h,g,p){return a(),i("div",null,[...t[0]||(t[0]=[r('<div class="hero-mark"><svg viewBox="0 0 96 96" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M8 26a8 8 0 0 1 8-8h20l8 8h36a8 8 0 0 1 8 8v42a8 8 0 0 1-8 8H16a8 8 0 0 1-8-8V26Z" fill="#CE7543"></path><path d="M8 40h80" stroke="#B3612F" stroke-width="3"></path></svg></div><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to “它是什么”">​</a></h2><p>ZenFile 是一个面向 Windows 10/11 x64 的原生文件管理器。界面上的右键菜单、属性页、 进度窗口、设置面板全部是自绘的像素，没有一处来自系统控件的默认皮肤。</p><p>项目受 <a href="https://github.com/LiteLoaderQQNT/LiteLoaderQQNT" target="_blank" rel="noreferrer">LiteLoaderQQNT</a> 启发， 设计取向是：<strong>原生程序同样可以兼顾资源占用与界面表现力</strong>——不必在「快」和「好看」之间二选一。</p><p><img src="'+s+'" alt="详细视图"></p><h2 id="核心数据" tabindex="-1">核心数据 <a class="header-anchor" href="#核心数据" aria-label="Permalink to “核心数据”">​</a></h2><p>全部来自本机实测（Windows 10 LTSC 21H2 / Ryzen 7 7435H / 16 GB / 2×NVMe）， 采集方法与口径见<a href="/zenfile/docs/performance.html">性能实测</a>。</p><table tabindex="0"><thead><tr><th>测试项目</th><th style="text-align:right;">ZenFile</th><th style="text-align:right;">资源管理器</th><th style="text-align:right;">Pulse</th></tr></thead><tbody><tr><td>空闲内存（RSS）</td><td style="text-align:right;"><strong>29.5 MB</strong></td><td style="text-align:right;">54.7 MB</td><td style="text-align:right;">214.5 MB</td></tr><tr><td>10 000 个小文件操作</td><td style="text-align:right;"><strong>5 109 文件/秒</strong></td><td style="text-align:right;">672</td><td style="text-align:right;">1 039</td></tr><tr><td>单个 4.7 GiB ISO 复制</td><td style="text-align:right;">5.78 s</td><td style="text-align:right;">5.89 s</td><td style="text-align:right;"><strong>4.23 s</strong></td></tr><tr><td>10 万文件目录加载</td><td style="text-align:right;"><strong>0.481 s</strong></td><td style="text-align:right;">0.620 s</td><td style="text-align:right;">0.967 s</td></tr><tr><td>删除 2 万文件期间 UI 延迟</td><td style="text-align:right;"><strong>p50 0.0 ms，无卡死</strong></td><td style="text-align:right;">—</td><td style="text-align:right;">—</td></tr></tbody></table><h2 id="三句话说明它怎么做到" tabindex="-1">三句话说明它怎么做到 <a class="header-anchor" href="#三句话说明它怎么做到" aria-label="Permalink to “三句话说明它怎么做到”">​</a></h2><p><strong>目录扫描靠缓存，不靠反复试探。</strong> 冲突判定原本对每个条目调一次 <code>Path::exists()</code>， 十万条目就是十万次 <code>GetFileAttributesW</code>——还要穿过杀软过滤驱动。改成按目录缓存 <code>read_dir</code> 快照（大小写不敏感对齐 NTFS）后，10 万条目从 3.07 s 降到 0.233 s（13×）。</p><p><strong>大文件不并行，走内核。</strong> 早期把 4.7 GiB 切成 64 块、数十线程并发，结果是 GB 级工作集、 缓存颠簸、CPU 饱和而吞吐没涨。实测发现单线程 <code>std::fs::copy</code> 比 32 线程分块<strong>快 45%、 CPU 少 3.4 倍</strong>——病根是「读进用户态缓冲再写出」的双拷贝，不是线程不够。 ≥256 MB 直接转 <code>CopyFileExW</code> + 进度回调。</p><p><strong>删除和批量重命名全在后台。</strong> 原先在 UI 线程同步跑，删 2 万个文件窗口直接失去响应。 现在全部走后台线程 + channel 回传，删除期间主线程延迟 p50 0.0 ms、p95 4.4 ms， 并且可以正常切换目录。</p><h2 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to “许可”">​</a></h2><p>Apache-2.0。受 LiteLoaderQQNT 启发。</p>',14)])])}const m=e(d,[["render",l]]);export{x as __pageData,m as default};
